
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_k_ol1_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_k_ol1", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([9.446789924775845e+01, 9.080308209172222e+01, 8.579190016252292e+01, 7.908955394270146e+01, 7.040456855573386e+01, 5.964744568609611e+01, 4.715185339323147e+01, 3.389403170002110e+01, 2.150186232782847e+01, 1.174276878900382e+01, 5.404843087560510e+00, 2.553667009034849e+00, 1.915240530135885e+00, 1.274088169059580e+00, 6.531828145252253e-01, 2.713247936613028e-01, 1.181812719469901e-01, 7.681050009011051e-02, 6.736698547522431e-02, 6.383220957136364e-02]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


